80	function resolveToolMatchers(
81	  value: unknown,
82	):
83	  | { kind: 'list'; matchers: TrajectoryStepMatcher[] }
84	  | { kind: 'count'; matcher: TrajectoryCountValue } {
85	  if (typeof value === 'string') {
86	    return {
87	      kind: 'list',
88	      matchers: [normalizeTrajectoryMatcher(value, 'tool')],
89	    };
90	  }
91	
92	  if (Array.isArray(value) && value.every((item) => typeof item === 'string')) {
93	    return {
94	      kind: 'list',
95	      matchers: value.map((item) => normalizeTrajectoryMatcher(item, 'tool')),
96	    };
97	  }
98	
99	  if (value && typeof value === 'object' && !Array.isArray(value)) {
100	    const matcher = normalizeTrajectoryMatcher(value as TrajectoryStepMatcher, 'tool');
101	    return {
102	      kind: 'count',
103	      matcher: {
104	        ...matcher,
105	        max:
106	          typeof (value as TrajectoryCountValue).max === 'number'
107	            ? (value as TrajectoryCountValue).max
108	            : undefined,
109	        min:
110	          typeof (value as TrajectoryCountValue).min === 'number'
111	            ? (value as TrajectoryCountValue).min
112	            : undefined,
113	      },
114	    };
115	  }
116	
117	  throw new Error(
118	    'trajectory:tool-used assertion must have a string, string array, or object value',
119	  );
120	}
