5	export type TrajectoryStepType = 'command' | 'message' | 'reasoning' | 'search' | 'span' | 'tool';
6	type TrajectoryAttributes = Record<string, unknown>;
7	
8	export interface TrajectoryStepMatcher {
9	  name?: string;
10	  pattern?: string;
11	  type?: TrajectoryStepType | TrajectoryStepType[];
12	}
