14	export interface TrajectoryStep {
15	  aliases: string[];
16	  attributes: TrajectoryAttributes;
17	  endTime?: number;
18	  name: string;
19	  spanId: string;
20	  spanName: string;
21	  startTime: number;
22	  statusCode?: number;
23	  statusMessage?: string;
24	  type: TrajectoryStepType;
25	}
