214	export function extractTrajectorySteps(trace: TraceData): TrajectoryStep[] {
215	  return [...(trace.spans || [])]
216	    .sort((a, b) => {
217	      const timeDiff = a.startTime - b.startTime;
218	      if (timeDiff !== 0) {
219	        return timeDiff;
220	      }
221	
222	      const endDiff = (a.endTime ?? a.startTime) - (b.endTime ?? b.startTime);
223	      if (endDiff !== 0) {
224	        return endDiff;
225	      }
226	
227	      return a.name.localeCompare(b.name);
228	    })
229	    .map((span) => {
230	      const toolName = extractToolName(span);
231	      const command = extractCommand(span);
232	      const searchQuery = extractSearchQuery(span);
233	
234	      let type: TrajectoryStepType = 'span';
235	      let name = span.name;
236	      const aliases = new Set<string>([span.name]);
237	
238	      if (toolName) {
239	        type = 'tool';
240	        name = toolName;
241	        aliases.add(toolName);
242	      } else if (command) {
243	        type = 'command';
244	        name = command;
245	        aliases.add(command);
246	        const executable = getCommandExecutable(command);
247	        if (executable) {
248	          aliases.add(executable);
249	        }
250	      } else if (searchQuery) {
251	        type = 'search';
252	        name = searchQuery;
253	        aliases.add(searchQuery);
254	      } else if (isReasoningSpan(span)) {
255	        type = 'reasoning';
256	        name = span.name;
257	        aliases.add('reasoning');
258	      } else if (isMessageSpan(span)) {
259	        type = 'message';
260	        name = span.name;
261	        aliases.add('message');
262	      }
263	
264	      return {
265	        aliases: [...aliases],
266	        attributes: span.attributes || {},
267	        endTime: span.endTime,
268	        name,
